// 전 카테고리 사전(목록) 대조 판정 — 사전에 없는 단어는 초성이 맞아도 오답.
// (예전엔 음식·동물·사물장소는 초성만 맞으면 아무 단어나 인정했는데, 없는 말 도배가 가능해 막았다)
// CHO_FREE_CATS는 이제 라운드 배정(1~4라운드)과 안내 문구 구분용으로만 쓰인다.
const CHO_FREE_CATS = new Set(['음식', '동물', '사물·장소']);

// 넓은 한국어 국어사전(35만 단어). 자유 카테고리에서 "실제로 있는 단어인지" 검사에 쓴다.
// → 초성만 맞는 엉터리 단어(예: '긓챠')는 걸러지고, 사전에 없는 진짜 단어는 통과한다.
// 파일이 없으면(로드 실패) 빈 Set → 관대 모드로 폴백(초성만 맞으면 인정).
const KOREAN_WORDS = new Set();
try {
  const wl = fs.readFileSync(path.join(__dirname, 'data', 'korean_words.txt'), 'utf8');
  for (const w of wl.split('\n')) { const t = w.trim(); if (t) KOREAN_WORDS.add(t); }
  console.log('[국어사전] 단어', KOREAN_WORDS.size + '개 로드');
} catch (e) { console.log('[국어사전] 로드 실패 — 관대 모드로 폴백', e.message); }
function isRealKoreanWord(w) { return KOREAN_WORDS.size === 0 || KOREAN_WORDS.has(w); }

// 카테고리별 초성 사전: 패턴 → 정답 단어 목록
const CHO_INDEX = {};
for (const [cat, words] of Object.entries(CHO_DATA)) {
  CHO_INDEX[cat] = new Map();
  for (const w of words) {
    const key = choseongOf(w);
    if (key.length < 2) continue;
    if (!CHO_INDEX[cat].has(key)) CHO_INDEX[cat].set(key, []);
    // 속편 숫자는 초성에 드러나지 않는다 — '미니언즈'와 '미니언즈2'가 서로 다른 정답인 양
    // 같은 문제에 나란히 뜨는 걸 막으려고 끝 숫자를 떼고 중복을 없앤다
    const norm = w.replace(/\s+/g, '').replace(/\d+$/, '');
    const list = CHO_INDEX[cat].get(key);
    if (norm && !list.includes(norm)) list.push(norm);
  }
}

// 초성 게임에 실제로 낼 만한 문제만 미리 추려둔다.
//  - 자유 카테고리: 초성 2~3글자 · 정답 3개 이상 (여러 명이 점수를 딸 수 있어야 한다)
//  - 제목 카테고리: 초성 2~4글자 · 정답 2개 이상 (긴 초성은 사실상 못 맞힌다)
const CHO_GOOD = {};
for (const [cat, m] of Object.entries(CHO_INDEX)) {
  const free = CHO_FREE_CATS.has(cat);
  CHO_GOOD[cat] = [...m.keys()].filter(k => {
    const cnt = m.get(k).length;
    return free ? (k.length >= 2 && k.length <= 3 && cnt >= 3)
                : (k.length >= 2 && k.length <= 4 && cnt >= 2);
  });
}

