// ---------- 물풍선 대작전 (크레이지 아케이드식) ----------
const CRAY_COLS = 15, CRAY_ROWS = 13, CRAY_CELL = 60;   // 격자 15x13, 셀 60유닛 → 900x780
const CRAY_MS = 180000;          // 3분 제한 (그 전에 최후 1인/1팀이 나오면 즉시 종료)
