const CRAY_TRAP_MS = 7000;       // 물방울에 갇혀 버티는 시간 (안 구해지면 탈락)
const CRAY_INV_MS = 1500;        // 구출·갇힘 직후 물줄기 무적 (연속으로 또 갇히는 것 방지)
const CRAY_BASE_SPEED = 250;     // 기본 이동 속도 (195 → 250: 시작부터 답답하지 않게)
const CRAY_SPEED_STEP = 22;      // 👟 하나당 증가
