const CRAY_THEME_N = 4;          // 맵 테마 수 (빌리지·얼음나라·사막·사탕나라) — 클라이언트 CRAY_THEMES와 같아야 한다

// ---------- 줄다리기 ----------
const PULL_PICK_MS = 15000;      // 학생이 좌우로 걸어가 팀을 고르는 시간
const PULL_ROUND_MS = 40000;     // 한 판 제한 시간 (넘으면 앞선 쪽 승)
